  L.marker([44.94815987473564,1.557262852539215],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[50,50],iconAnchor:[25,25],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Cuzance (Lot)</strong><br>–Vers 1875, plus de 4000 monnaies gauloises en argent, presque toutes du type « à la croix », dont une du type de Luctérios, ont été trouvées près du Bournissard, hameau de la commune de Cuzance. <a href="https://www.uxellodunum.com/uploads/1/4/8/8/148875485/les_monnaies_à_la_croix_texte_v3.pdf" target="_blank" rel="noreferrer noopener">Girault, J-P. <em>et al</em>. Le trésor du Bournissard. Ensemble de monnaies gauloises à la croix dites de Cuzance</a>. ❦ <a href="https://www.uxellodunum.com/uploads/1/4/8/8/148875485/les_monnaie_du_puy_dissolud_v8_planche3_v2_optimise.pdf" target="_blank" rel="noreferrer noopener">Girault, J-P. Les monnaies trouvées au Puy d’Issolud et à la Fontaine de Loulié.</a> ❦ Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
