  L.marker([45.008526,0.987847],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[13,13],iconAnchor:[6,6],popupAnchor:[0,-10]})}).bindPopup('✱&nbsp;<strong>Rouffignac (Dordogne)</strong><br>–Mis au jour vers 1960. Le trésor contenait 11 monnaies: 3 monnaies à la croix de la série Belvès, associées à 7 fractions cadurques et une monnaie pétrocore au monstre hybride. <a href="https://hal.science/hal-02974081/document" target="_blank" rel="noreferrer noopener">Chevillot, C. et al. Rouffignac, une grotte-sanctuaire du IIe âge du Fer.</a> ❦ Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
