  L.marker([44.842594,0.653506],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[44,44],iconAnchor:[22,22],popupAnchor:[0,-10]})}).bindPopup('✱&nbsp;<strong>Saint-Capraise-de-Lalinde (Dordogne)</strong><br>–Mis au jour au xixe s. Le trésor contenait plus de 2 kg de monnaies à la croix. Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
