  L.marker([44.608194,0.568499],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[40,40],iconAnchor:[20,20],popupAnchor:[0,-10]})}).bindPopup('✱&nbsp;<strong><em>Parpaillou</em>, Montauriol (Lot-et-Garonne)</strong><br>–Le lot monétaire se compose de 198 monnaies celtiques en argent. La totalité des pièces se rattache au même ensemble monétaire, celui des monnaies à la croix: : 92 de la série Belvès, 65 Causé, 21 à la tête triangulaire, 14 au panache, 4 flamboyantes et 2 cubistes. <a href="https://hal.science/hal-02072136/" target="_blank" rel="noreferrer noopener">Hiriart, E. Un nouveau trésor de monnaies à la croix à Montauriol (Lot-et-Garonne).</a> ❦ Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
  L.marker([43.418832631586085,1.3542531245199865],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2025/03/a_la_croix.svg',iconSize:[10,10],iconAnchor:[5,5],popupAnchor:[0,-10]})}).bindPopup('<strong>Eaunes (Haute-Garonne)</strong><br>–1 monnaie en argent <em>à la croix</em> (<em>CAG</em> 31/1, p. 170).').addTo(lyALaCroix);
