  L.marker([43.374486182603334,1.0798102755287],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2025/03/a_la_croix.svg',iconSize:[10,10],iconAnchor:[5,5],popupAnchor:[0,-10]})}).bindPopup('<strong>Lautignac (Haute-Garonne)</strong><br>–1 monnaie <em>à la croix</em> (<em>CAG</em> 31/1, p. 200).').addTo(lyALaCroix);
