  L.marker([44.02903483449351,-0.4430104926718737],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2025/03/a_la_croix.svg',iconSize:[26,26],iconAnchor:[13,13],popupAnchor:[0,-10]})}).bindPopup('<strong>Maillères (Landes)</strong><br>–1 dizaine de monnaies à la croix. Ce site a été pillé par des utilisateurs de détecteurs de métaux à la fin des années 1990.<br><a href="https://www.academia.edu/35969012/Occupation_du_sol_en_Aquitaine_romaine_L_exemple_landais_de_partement_des_Landes_" target="_blank" rel="noreferrer noopener">Cabes, S. &amp; Vignaud, D. Occupation du sol en Aquitaine romaine - L’exemple landais (département des Landes).</a>').addTo(lyALaCroix);
