  L.marker([43.50803875819334,1.4021702211883107],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[40,40],iconAnchor:[20,20],popupAnchor:[0,-10]})}).bindPopup('<strong><em>Les Ramiers,</em></strong> <strong>Lacroix-Falgarde (Haute-Garonne)</strong><br>–42 pièces gauloises en argent «&nbsp;à la croix de type cubiste au dauphin&nbsp;».<br>–12 exemplaires à légende ibérique&nbsp;<em>akerekonton</em>. <a href="https://journals.openedition.org/adlfi/10867?lang=en" target="_blank" rel="noreferrer noopener">“Lacroix-Falgarde – Les Ramiers”&nbsp;[Note of archaeological project],&nbsp;<em>ADLFI. Archéologie de la France - Informations</em>&nbsp;[Online], Occitania.</a> ❦ Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
  L.marker([44.09915765487268,0.793026472651957],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[44,44],iconAnchor:[22,22],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Dunes (Tarn-et-Garonne)</strong><br>–Mis au jour au xxe s. Le trésor contenait 497 monnaies à la croix, dont 322 flamboyantes, 74 au panache, 43 cubistes, 36 à la tête triangulaire et une à la légende ibérique. (<a href="https://www.persee.fr/doc/galia_0016-4119_1983_num_41_2_1904" target="_blank" rel="noreferrer noopener"><em>Gallia</em>, 1983, 41-2, p. 502</a>) ❦ Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
  L.marker([44.125928,1.240931],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[26,26],iconAnchor:[13,13],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Lafrançaise (Tarn-et-Garonne)</strong><br>Mis au jour dans les années 1990. Le trésor contenait au moins 91 monnaies à la croix: 57 de la série aux motifs géométriques, 17 Cuzance, 15 à la tête triangulaire tardive, une aux mèches ondulées et une Causé, associées à deux Kaletedoy et une EFE. Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
  L.marker([44.25601,1.137876],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[44,44],iconAnchor:[22,22],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Lauzerte (Tarn-et-Garonne)</strong><br>Mis au jour en 1982. Le trésor contenait au moins 290 monnaies à la croix, dont au moins 220 de la série cubiste, 32 à la tête triangulaire, 10 flamboyantes, 7 au panache et une précoce. Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
  L.marker([43.49964742266276,1.3942012765233265],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[40,40],iconAnchor:[20,20],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Pinsaguel (Haute-Garonne)</strong><br>–En 1866 fut signalée une découverte de monnaies « à la croix » dans la commune de Pinsaguel. Selon les dires de l\'inventeur, un vase aurait été brisé par le soc d\'une charrue et 119 monnaies auraient été recueillies. <a href="https://www.persee.fr/doc/palla_0031-0387_1986_hos_1_1_1176" target="_blank" rel="noreferrer noopener">Depeyrot, G. Trois documents sur les trésors des monnaies à «&nbsp;la croix&nbsp;».</a> ❦ Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>.').addTo(lyALaCroix);
  L.marker([45.19804078742359,-0.818829113173121],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[50,50],iconAnchor:[25,25],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Saint-Sauveur (Gironde)</strong><br>Mis au jour vers 1866. Le trésor contenait 3546 monnaies à la croix (10,25 kg), dont au moins 135 de la série cubiste, 16 à la tête triangulaire et 13 au panaché. Hiriart, E.&nbsp;<em>Catalogue des Monnaies Celtiques, 2, Les monnaies à la croix</em>. ❦ <a href="https://www.persee.fr/doc/palla_0031-0387_1986_hos_1_1_1176" target="_blank" rel="noreferrer noopener">Depeyrot, G. Trois documents sur les trésors des monnaies à «&nbsp;la croix&nbsp;».</a>').addTo(lyALaCroix);
  L.marker([43.11410455232944,1.6094193174680598],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[20,20],iconAnchor:[10,10],popupAnchor:[0,-10]})}).bindPopup('<strong>Pamiers (Ariège)</strong><br>–17 monnaies «&nbsp;à la croix&nbsp;» qui auraient appartenu à un trésor anciennement mis a jour à Pamiers (<em>CAG</em> 09, p. 132). <a href="https://www.jstor.org/stable/42681849" target="_blank" rel="noreferrer noopener">Allen, D. F. Monnaies-à-la croix.</a>').addTo(lyALaCroix);
  L.marker([43.48871700259272,1.0077459321902058],{icon:L.icon({iconUrl:'https://tabulapyrenaei.eu/wp-content/uploads/2026/01/a_la_croix_tresor.svg',iconSize:[20,20],iconAnchor:[10,10],popupAnchor:[0,-10]})}).bindPopup('✱ <strong>Savignac-Mona (Gers)</strong><br>–Trésor d’une vingtaine de pièces de monnaie à la croix des Volques-Tectosages (<a href="https://savignac-mona.fr/histoire-et-patrimoine/">savignac-mona.fr/</a>).').addTo(lyALaCroix);
